import { mkdir, readdir, readFile, rmdir, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { ulid } from 'ulid';
import { USERNAME_RE, validateUsername } from '#lib/geo/username.ts';
import { dataDir, StorageError, ULID_RE } from './storage.ts';

/** What `data/{userName}/user.json` holds. */
export interface UserRecord {
	/** A ULID, generated by the server and never reused. Not a secret. */
	userId: string;
	username: string;
	createdAt: string;
	/** Tokens issued before this time are rejected (revocation). Null means no cutoff. */
	tokensValidAfter: string | null;
}

/**
 * The directory that holds a user's `user.json` and route files: `data/{userName}/`. The name is
 * validated first, so it is safe as a path segment.
 */
export function userDir(username: string): string {
	if (!USERNAME_RE.test(username)) throw new StorageError(400, 'invalid username');
	return join(dataDir(), username);
}

function isCode(e: unknown, code: string): boolean {
	return (e as NodeJS.ErrnoException | undefined)?.code === code;
}

/** Checks a parsed `user.json`. Returns null if it is not a well-formed record for that name. */
function toUserRecord(raw: unknown, username: string): UserRecord | null {
	if (typeof raw !== 'object' || raw === null) return null;
	const r = raw as Record<string, unknown>;
	if (typeof r.userId !== 'string' || !ULID_RE.test(r.userId)) return null;
	if (r.username !== username) return null; // the file must belong to its directory
	if (typeof r.createdAt !== 'string') return null;
	const after = r.tokensValidAfter;
	if (after !== null && (typeof after !== 'string' || Number.isNaN(Date.parse(after)))) return null;
	return { userId: r.userId, username, createdAt: r.createdAt, tokensValidAfter: after };
}

/**
 * Looks a user up by name (case-insensitively). Returns null when there is no such user, the
 * name is not a valid user name, or the record on disk is unreadable or inconsistent.
 */
export async function getUser(name: string): Promise<UserRecord | null> {
	const username = name.toLowerCase();
	if (!USERNAME_RE.test(username)) return null;
	try {
		const raw = JSON.parse(await readFile(join(userDir(username), 'user.json'), 'utf8'));
		return toUserRecord(raw, username);
	} catch (e) {
		if (isCode(e, 'ENOENT') || isCode(e, 'ENOTDIR') || e instanceof SyntaxError) return null;
		throw e;
	}
}

/** How many users exist: the directories under `data/` whose names are valid user names. */
export async function countUsers(): Promise<number> {
	try {
		const entries = await readdir(dataDir(), { withFileTypes: true });
		return entries.filter((e) => e.isDirectory() && USERNAME_RE.test(e.name)).length;
	} catch (e) {
		if (isCode(e, 'ENOENT')) return 0;
		throw e;
	}
}

/**
 * Signs a new user up: validates the name, then claims `data/{userName}/` and writes its
 * `user.json` with a new ULID user ID.
 *
 * The name is claimed with a non-recursive `mkdir`, which is atomic: if two sign-ups race for
 * the same name, exactly one succeeds and the other gets a 409. The name is lowercased first,
 * so `Demo` and `demo` are the same name.
 *
 * Errors (all `StorageError`): 400 invalid or reserved name, 409 taken, 503 user cap reached.
 */
export async function createUser(
	rawName: string,
	opts: { maxUsers?: number } = {}
): Promise<UserRecord> {
	const username = rawName.trim().toLowerCase();
	const problem = validateUsername(username);
	if (problem) throw new StorageError(400, problem);

	if (opts.maxUsers !== undefined && (await countUsers()) >= opts.maxUsers) {
		throw new StorageError(503, 'Sign-ups are closed for now.');
	}

	await mkdir(dataDir(), { recursive: true });
	const dir = userDir(username);
	try {
		await mkdir(dir); // not recursive: fails with EEXIST if the name is already claimed
	} catch (e) {
		if (isCode(e, 'EEXIST')) throw new StorageError(409, 'That name is taken.');
		throw e;
	}

	const record: UserRecord = {
		userId: ulid(),
		username,
		createdAt: new Date().toISOString(),
		tokensValidAfter: null
	};
	try {
		// 'wx': never overwrite an existing file.
		await writeFile(join(dir, 'user.json'), JSON.stringify(record, null, 2) + '\n', { flag: 'wx' });
	} catch (e) {
		// Do not leave a claimed name with no user behind. The directory is the one made just above.
		await rmdir(dir).catch(() => {});
		throw e;
	}
	return record;
}
